MIKU_HISTORY_FILE = os.path.join(os.path.expanduser("~"), ".miku_chat_history.json")

def load_miku_history() -> List[dict]:
    try:
        if os.path.exists(MIKU_HISTORY_FILE):
            with open(MIKU_HISTORY_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception:
        pass
    return []

def save_miku_history(records: List[dict]) -> None:
    try:
        with open(MIKU_HISTORY_FILE, "w", encoding="utf-8") as f:
            json.dump(records, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

