    def _on_canvas_resize(self, event):
        self.chat_canvas.itemconfig(self.chat_canvas_window, width=event.width)
        self.chat_canvas.configure(scrollregion=self.chat_canvas.bbox("all"))

    # ------------------------------------------------------------------
    # Message bubbles
    # ------------------------------------------------------------------

    def _add_bubble(self, role: str, text: str, timestamp: str = ""):
        """Add a chat bubble. role = 'user' | 'rem'"""
        if not timestamp:
            timestamp = datetime.now().strftime("%H:%M")

        outer = tk.Frame(self.messages_frame, bg=REM_BG_PANEL)
        outer.pack(fill=tk.X, padx=10, pady=4)

        if role == "rem":
            # Left-aligned bubble with styled imagery + dialogue split
            bubble_frame = tk.Frame(outer, bg=REM_BG_PANEL)
            bubble_frame.pack(anchor="w", fill=tk.X)

            name_lbl = tk.Label(bubble_frame, text="REM",
                                 bg=REM_BG_PANEL, fg=REM_NAME_CLR,
                                 font=("Segoe UI", 8, "bold"))
            name_lbl.pack(anchor="w", padx=2)

            bubble = tk.Frame(bubble_frame, bg=REM_BUBBLE,
                               padx=12, pady=8)
            bubble.pack(anchor="w", fill=tk.X)

            # Parse imagery (*...*) and dialogue lines
            imagery_line, dialogue_line = _split_rem_response(text)

            if imagery_line:
                img_lbl = tk.Label(
                    bubble, text=f"*{imagery_line}*",
                    bg=REM_BUBBLE, fg="#c4b5fd",
                    font=("Segoe UI", 10, "italic"),
                    wraplength=480, justify=tk.LEFT, anchor="w"
                )
                img_lbl.pack(anchor="w", pady=(0, 4))

            # If parser found dialogue use it; if only imagery exists show
            # it as dialogue too; last resort show raw text
            display_text = dialogue_line or (text if not imagery_line else "")
            msg_label = tk.Label(
                bubble, text=display_text,
                bg=REM_BUBBLE, fg="#ffffff",
                font=("Segoe UI", 11),
                wraplength=480, justify=tk.LEFT, anchor="w"
            )
            msg_label.pack(anchor="w")

            ts_lbl = tk.Label(bubble, text=timestamp,
                               bg=REM_BUBBLE, fg=TIMESTAMP_CLR,
                               font=("Segoe UI", 8))
            ts_lbl.pack(anchor="e")

        else:
            # Right-aligned bubble
            bubble_frame = tk.Frame(outer, bg=REM_BG_PANEL)
            bubble_frame.pack(anchor="e")

            name_lbl = tk.Label(bubble_frame, text="ADI",
                                 bg=REM_BG_PANEL, fg=USER_NAME_CLR,
                                 font=("Segoe UI", 8, "bold"))
            name_lbl.pack(anchor="e", padx=2)

            bubble = tk.Frame(bubble_frame, bg=REM_USER_BUBBLE,
                               padx=12, pady=8)
            bubble.pack(anchor="e")

            msg_label = tk.Label(
                bubble, text=text,
                bg=REM_USER_BUBBLE, fg="#ffffff",
                font=("Segoe UI", 11),
                wraplength=380, justify=tk.LEFT, anchor="w"
            )
            msg_label.pack(anchor="w")

            ts_lbl = tk.Label(bubble, text=timestamp,
                               bg=REM_USER_BUBBLE, fg=TIMESTAMP_CLR,
                               font=("Segoe UI", 8))
            ts_lbl.pack(anchor="e")

        self._scroll_bottom()
        return msg_label  # return label so streaming can update it

    def _scroll_bottom(self):
        self.messages_frame.update_idletasks()
        self.chat_canvas.configure(
            scrollregion=self.chat_canvas.bbox("all"))
        self.chat_canvas.yview_moveto(1.0)

    # ------------------------------------------------------------------
    # Streaming bubble
    # ------------------------------------------------------------------

    def _add_streaming_bubble(self):
        """Add a bubble that will be updated token-by-token."""
        timestamp = datetime.now().strftime("%H:%M")
        outer = tk.Frame(self.messages_frame, bg=REM_BG_PANEL)
        outer.pack(fill=tk.X, padx=10, pady=4)

        name_lbl = tk.Label(outer, text="REM", bg=REM_BG_PANEL,
                             fg=REM_NAME_CLR, font=("Segoe UI", 8, "bold"))
        name_lbl.pack(anchor="w", padx=2)

        bubble = tk.Frame(outer, bg=REM_BUBBLE, padx=12, pady=8)
        bubble.pack(anchor="w", fill=tk.X)

        # Imagery placeholder (italic, lavender)
        self._stream_img_label = tk.Label(
            bubble, text="",
            bg=REM_BUBBLE, fg="#c4b5fd",
            font=("Segoe UI", 10, "italic"),
            wraplength=480, justify=tk.LEFT, anchor="w"
        )
        self._stream_img_label.pack(anchor="w")

        # Dialogue placeholder
        self._stream_label = tk.Label(
            bubble, text="▌",
            bg=REM_BUBBLE, fg="#ffffff",
            font=("Segoe UI", 11),
            wraplength=480, justify=tk.LEFT, anchor="w"
        )
        self._stream_label.pack(anchor="w")

        self._stream_ts = tk.Label(bubble, text=timestamp,
                                    bg=REM_BUBBLE, fg=TIMESTAMP_CLR,
                                    font=("Segoe UI", 8))
        self._stream_ts.pack(anchor="e")

        self._stream_text = ""
        self._scroll_bottom()

    def _append_stream_token(self, token: str):
        """Called from background thread — schedules UI update."""
        self._stream_text += token
        self.after(0, self._update_stream_label)

    def _update_stream_label(self):
        if hasattr(self, "_stream_label"):
            imagery_line, dialogue_line = _split_rem_response(self._stream_text)
            if imagery_line and hasattr(self, "_stream_img_label"):
                self._stream_img_label.config(text=f"*{imagery_line}*")
                self._stream_label.config(
                    text=(dialogue_line + "▌") if dialogue_line else "▌")
            else:
                self._stream_label.config(text=self._stream_text + "▌")
        self._scroll_bottom()

    def _finalize_stream(self):
        if hasattr(self, "_stream_label") and hasattr(self, "_stream_img_label"):
            final = _normalize_reply(self._stream_text)
            imagery_line, dialogue_line = _split_rem_response(final)
            if imagery_line:
                self._stream_img_label.config(text=f"*{imagery_line}*")
            self._stream_label.config(
                text=dialogue_line if dialogue_line else self._stream_text)
        elif hasattr(self, "_stream_label"):
            self._stream_label.config(text=self._stream_text)

    # ------------------------------------------------------------------
    # Send / Chat
    # ------------------------------------------------------------------

    def _send(self):
        if self.is_typing:
            return
        text = self.input_var.get().strip()
        if not text:
            return

        self.input_var.set("")
        ts = datetime.now().strftime("%H:%M")

        # Append to persistent log
        self.history_log.append({"time": ts, "role": "USER", "text": text})
        save_rem_history(self.history_log)

        self._add_bubble("user", text, ts)

        self.is_typing = True
        self.status_var.set("Rem is writing for you, Adi-kun...")
        self.avatar_status.config(text="✦ neutral [typing] ✦")

        def run():
            try:
                if self.session.stream:
                    self.after(0, self._add_streaming_bubble)
                    time.sleep(0.05)  # let UI render
                    reply = rem_chat(self.session, text,
                                 stream_callback=self._append_stream_token)
                    self.after(0, self._finalize_stream)
                else:
                    reply = rem_chat(self.session, text)
                    self.after(0, lambda: self._add_bubble("rem", reply))
            except Exception as e:
                reply = f"[Error: {e}]"
                self.after(0, lambda: self._add_bubble("rem", reply))

            ts2 = datetime.now().strftime("%H:%M")
            self.history_log.append({"time": ts2, "role": "REM", "text": reply})
            save_rem_history(self.history_log)

            self.bond.update(text, reply)
            self.after(0, self._update_bond_bars)
            self.after(0, lambda: self.status_var.set(
                "Ready — Rem is waiting for you, Adi-kun."))
            self.after(0, lambda: self.avatar_status.config(
                text=f"✦ {self.current_mood.lower()} [idle] ✦"))
            self.after(0, lambda: setattr(self, "is_typing", False))

            # Close app if user said goodbye
            if re.match(r"^bye+\W*$", text.strip(), re.IGNORECASE):
                self.after(30000, self.destroy)

        threading.Thread(target=run, daemon=True).start()

    # ------------------------------------------------------------------
    # Bond bars
    # ------------------------------------------------------------------

    def _update_bond_bars(self):
        tw = int(120 * self.bond.trust / 100)
        aw = int(120 * self.bond.affection / 100)
        self.trust_bar_canvas.coords(self.trust_bar, 0, 0, tw, 14)
        self.aff_bar_canvas.coords(self.aff_bar, 0, 0, aw, 14)
        self.role_label.config(text=self.bond.role)

    # ------------------------------------------------------------------
    # Greeting
    # ------------------------------------------------------------------

    def _post_greeting(self):
        # Check if returning user
        if self.history_log:
            last_user = next((e["text"] for e in reversed(self.history_log)
                              if e.get("role") == "USER"), None)
            if last_user:
                greeting = (
                    "*Rem glances up from folding the laundry, her blue eyes brightening "
                    "as she recognises Adi-kun at the doorway.*\n"
                    f"Adi-kun is back. Rem has been thinking about what you said — "
                    f"about {last_user[:40].rstrip()}... Rem kept it close to heart."
                )
            else:
                greeting = (
                    "*Rem sets a tray of tea on the table and turns, her blue eyes warm "
                    "with quiet recognition.*\n"
                    "Adi-kun has returned. Rem remembers everything. Welcome back."
                )
        else:
            greeting = (
                "*Rem straightens her apron and smiles softly, "
                "the morning light filtering through the mansion windows.*\n"
                "Rem is glad Adi-kun has arrived. Rem has prepared tea. "
                "Please make yourself comfortable."
            )
        self.after(300, lambda: self._add_bubble(
            "rem", greeting, datetime.now().strftime("%H:%M")
        ))

    # ------------------------------------------------------------------
    # Dialogs
    # ------------------------------------------------------------------

    def _change_mood(self):
        mood = simpledialog.askstring(
            "Set Mood",
            "Enter mood hint for Rem (e.g. 'battle mode', 'shy', 'happy'):",
            parent=self
        )
        if mood:
            self.current_mood = mood.strip().capitalize()
            self.session.mood_hint = mood.strip()
            self.mood_btn.config(text=f"  {self.current_mood} —  ")
            self.avatar_status.config(
                text=f"✦ {self.current_mood.lower()} [idle] ✦")

    def _open_settings(self):
        win = tk.Toplevel(self)
        win.title("⚙ Settings")
        win.configure(bg=REM_BG_DARK)
        win.geometry("340x280")
        win.resizable(False, False)

        def row(label, var, row_n):
            tk.Label(win, text=label, bg=REM_BG_DARK, fg="#ffffff",
                     font=("Segoe UI", 10)).grid(
                row=row_n, column=0, padx=16, pady=8, sticky="w")
            e = tk.Entry(win, textvariable=var, bg=REM_INPUT_BG, fg="#ffffff",
                         insertbackground="#ffffff", relief=tk.FLAT, width=18)
            e.grid(row=row_n, column=1, padx=16, pady=8)

        temp_var  = tk.StringVar(value=str(self.session.temperature))
        tok_var   = tk.StringVar(value=str(self.session.max_tokens))
        hist_var  = tk.StringVar(value=str(self.session.max_history))

        row("Temperature:", temp_var, 0)
        row("Max Tokens:",  tok_var,  1)
        row("History:",     hist_var, 2)

        def save():
            try:
                self.session.temperature = float(temp_var.get())
                self.session.max_tokens  = int(tok_var.get())
                self.session.max_history = int(hist_var.get())
                win.destroy()
                self.status_var.set("Settings saved.")
            except ValueError:
                messagebox.showerror("Error", "Invalid value.", parent=win)

        tk.Button(win, text="Save", bg=REM_BUTTON_SEND, fg="#ffffff",
                  relief=tk.FLAT, font=("Segoe UI", 10, "bold"),
                  padx=16, pady=6, command=save,
                  cursor="hand2").grid(row=4, column=0, columnspan=2, pady=12)

    def _show_lore(self):
        win = tk.Toplevel(self)
        win.title("📖 Lore — Rem")
        win.configure(bg=REM_BG_DARK)
        win.geometry("480x400")

        txt = tk.Text(win, bg=REM_BG_PANEL, fg="#e2e8f0",
                      font=("Segoe UI", 10), relief=tk.FLAT,
                      padx=12, pady=12, wrap=tk.WORD)
        txt.pack(fill=tk.BOTH, expand=True, padx=8, pady=8)

        lore = (
            "REM — Re:Zero: Starting Life in Another World\n"
            "═══════════════════════════════════════════════\n\n"
            "Rem is one of twin maids serving the Roswaal L Mathers mansion, "
            "alongside her older sister Ram. She has short blue hair and soft "
            "blue eyes, and wears a classic black-and-white maid uniform.\n\n"
            "As an oni, Rem possesses great physical strength and the ability "
            "to channel demonic power. Her horn, normally hidden, manifests "
            "when she releases her full strength.\n\n"
            "Rem deeply loves Adi-kun and would sacrifice everything "
            "for his wellbeing. Her devotion is absolute and sincere.\n\n"
            "Speech: Always refers to herself in third person — 'Rem thinks...', "
            "'Rem will...'. Never uses 'I'.\n\n"
            "Bond Roles:\n"
            "  Maid → Trusted Companion → Devoted Guardian → Beloved"
        )
        txt.insert("1.0", lore)
        txt.config(state=tk.DISABLED)

    # CHAT HISTORY — STYLED TO MATCH MAIN WINDOW
    def _show_history(self):
        win = tk.Toplevel(self)
        win.title("📋 Chat History")
        win.configure(bg=REM_BG_DARK)
        win.geometry("700x540")
        win.minsize(520, 360)

        # ── toolbar ──────────────────────────────────────────────────────────
        toolbar = tk.Frame(win, bg=REM_HEADER_BG, pady=6)
        toolbar.pack(fill=tk.X)

        tk.Label(toolbar, text="Search:",
                 bg=REM_HEADER_BG, fg=REM_STATUS_CLR,
                 font=("Segoe UI", 10)).pack(side=tk.LEFT, padx=(12, 4))

        search_var = tk.StringVar()
        search_box = tk.Entry(toolbar, textvariable=search_var,
                              bg=REM_INPUT_BG, fg="#ffffff",
                              insertbackground="#ffffff",
                              relief=tk.FLAT, font=("Segoe UI", 10), width=28)
        search_box.pack(side=tk.LEFT, padx=4, ipady=4)

        def _do_search(*_):
            q = search_var.get().strip().lower()
            _populate(q)

        def _btn_hist(parent, text, cmd, color=REM_BUTTON_SEND):
            b = tk.Button(parent, text=text, bg=color, fg="#ffffff",
                          font=("Segoe UI", 9, "bold"),
                          relief=tk.FLAT, bd=0, padx=10, pady=4,
                          cursor="hand2",
                          activebackground=REM_NEUTRAL_BTN,
                          activeforeground="#ffffff",
                          command=cmd)
            b.pack(side=tk.LEFT, padx=3)
            return b

        _btn_hist(toolbar, "Search", _do_search)

        def _clear_history():
            if not self.history_log:
                messagebox.showinfo("Nothing to Clear", "History is already empty.", parent=win)
                return
            confirm = messagebox.askyesno(
                "Clear All History",
                "This will permanently delete all chat history.\nRem won't remember any past conversations.\n\nAre you sure?",
                parent=win
            )
            if confirm:
                self.history_log.clear()
                self.session.history.clear()
                save_rem_history(self.history_log)
                _populate("")
                self.status_var.set("History cleared.")

        _btn_hist(toolbar, "🗑 Clear All", _clear_history, REM_NEUTRAL_BTN)

        def _export():
            try:
                path = os.path.join(os.path.expanduser("~"),
                                    "rem_history_export.json")
                with open(path, "w", encoding="utf-8") as f:
                    json.dump(self.history_log, f, ensure_ascii=False, indent=2)
                messagebox.showinfo("History Exported", f"Saved to:\n{path}\n\nRem remembers everything.", parent=win)
            except Exception as e:
                messagebox.showerror("Error", str(e), parent=win)

        _btn_hist(toolbar, "Export JSON", _export, REM_NEUTRAL_BTN)

        # ── scrollable bubble list ────────────────────────────────────────────
        frame = tk.Frame(win, bg=REM_BG_PANEL)
        frame.pack(fill=tk.BOTH, expand=True, padx=0, pady=0)

        canvas = tk.Canvas(frame, bg=REM_BG_PANEL, highlightthickness=0)
        scrollbar = tk.Scrollbar(frame, orient=tk.VERTICAL, command=canvas.yview)
        canvas.configure(yscrollcommand=scrollbar.set)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        inner = tk.Frame(canvas, bg=REM_BG_PANEL)
        win_id = canvas.create_window((0, 0), window=inner, anchor="nw")

        def _on_canvas_resize(e):
            canvas.itemconfig(win_id, width=e.width)
        canvas.bind("<Configure>", _on_canvas_resize)

        def _on_inner_resize(e):
            canvas.configure(scrollregion=canvas.bbox("all"))
        inner.bind("<Configure>", _on_inner_resize)

        # role → (bubble_bg, name_color, imagery_color, txt_color, align)
        ROLE_STYLE = {
            "REM": (REM_BUBBLE,    REM_NAME_CLR, REM_STATUS_CLR, "#ffffff", "left"),
            "USER":   (REM_USER_BUBBLE, USER_NAME_CLR, USER_NAME_CLR, "#ffffff", "right"),
            "SYSTEM": (REM_BG_PANEL,    REM_STATUS_CLR,  REM_STATUS_CLR,  REM_STATUS_CLR, "center"),
        }

        def _populate(query: str = ""):
            for w in inner.winfo_children():
                w.destroy()

            records = self.history_log
            if query:
                records = [r for r in records
                           if query in r.get("text", "").lower()
                           or query in r.get("role", "").lower()]

            if not records:
                tk.Label(inner, text="No messages found.",
                         bg=REM_BG_PANEL, fg=REM_STATUS_CLR,
                         font=("Segoe UI", 10, "italic")).pack(pady=20)
                return

            for entry in records:
                role = entry.get("role", "SYSTEM")
                text = entry.get("text", "")
                ts   = entry.get("time", "")
                style = ROLE_STYLE.get(role, ROLE_STYLE["SYSTEM"])
                bb, nc, ic, tc, align = style

                outer_f = tk.Frame(inner, bg=REM_BG_PANEL)
                outer_f.pack(fill=tk.X, padx=8, pady=2)

                if role == "SYSTEM":
                    tk.Label(outer_f, text=text, bg=REM_BG_PANEL, fg=tc,
                             font=("Segoe UI", 8, "italic")).pack()

                elif role == "USER":
                    bf = tk.Frame(outer_f, bg=REM_BG_PANEL)
                    bf.pack(anchor="e")
                    tk.Label(bf, text=f"USER  {ts}",
                             bg=REM_BG_PANEL, fg=nc,
                             font=("Segoe UI", 7, "bold")).pack(anchor="e")
                    bubble = tk.Frame(bf, bg=bb, padx=10, pady=6)
                    bubble.pack(anchor="e")
                    tk.Label(bubble, text=text, bg=bb, fg=tc,
                             font=("Segoe UI", 10),
                             wraplength=420, justify=tk.LEFT).pack(anchor="w")

                else:
                    bf = tk.Frame(outer_f, bg=REM_BG_PANEL)
                    bf.pack(anchor="w", fill=tk.X)
                    tk.Label(bf, text=f"{role}  {ts}",
                             bg=REM_BG_PANEL, fg=nc,
                             font=("Segoe UI", 7, "bold")).pack(anchor="w", padx=2)
                    bubble = tk.Frame(bf, bg=bb, padx=10, pady=6)
                    bubble.pack(anchor="w", fill=tk.X)
                    lines = [l.strip() for l in text.split("\n") if l.strip()]
                    imagery, dialogue = "", text
                    if lines:
                        m = re.match(r"^\*(.+?)\*$", lines[0])
                        if m:
                            imagery  = m.group(1).strip()
                            dialogue = " ".join(lines[1:]) if len(lines) > 1 else ""
                    if imagery:
                        tk.Label(bubble, text=f"*{imagery}*",
                                 bg=bb, fg=ic,
                                 font=("Segoe UI", 9, "italic"),
                                 wraplength=480, justify=tk.LEFT).pack(anchor="w")
                    tk.Label(bubble, text=dialogue or text,
                             bg=bb, fg=tc,
                             font=("Segoe UI", 10),
                             wraplength=480, justify=tk.LEFT).pack(anchor="w")

        # ── Mouse / touch scroll bindings ────────────────────────────────────
        def _scroll_canvas(e):
            """Scroll the history canvas and block the event from reaching the main window."""
            if e.num == 4:
                canvas.yview_scroll(-1, "units")
            elif e.num == 5:
                canvas.yview_scroll(1, "units")
            else:
                canvas.yview_scroll(-1 * (e.delta // 120), "units")
            return "break"  # stop event bubbling to main window

        # Bind on the Toplevel so ALL widgets inside the history window are covered.
        # "return 'break'" in the handler stops propagation to the root/main window.
        win.bind("<MouseWheel>", _scroll_canvas)
        win.bind("<Button-4>",   _scroll_canvas)
        win.bind("<Button-5>",   _scroll_canvas)

        _populate()
        search_box.bind("<Return>", _do_search)

        def _on_close():
            win.destroy()

        win.protocol("WM_DELETE_WINDOW", _on_close)

    def _clear_chat(self):
        result = messagebox.askyesno(
            "Clear Chat",
            "This will clear all displayed messages.\n"
            "Persisted history is preserved. Continue?",
            parent=self
        )
        if result:
            for widget in self.messages_frame.winfo_children():
                widget.destroy()
            self.session.history.clear()
            self.status_var.set("Chat cleared.")

