# GUI
# ---------------------------------------------------------------------------

# AFTER
class KiritoApp(tk.Frame):
    _OWN_BG = KIRITO_BG_DARK  # captured at class-definition time
    def __init__(self, parent_frame, session: KiritoSession):
        super().__init__(parent_frame, bg=self._OWN_BG)
        self.pack(fill="both", expand=True)
        self.session        = session
        self.bond           = MentorTracker()
        self.history_log    = load_kirito_history()   # persistent log
        self.is_typing      = False
        self.current_mood   = "Neutral"
        self.stream_buffer  = ""
        self.kirito_image      = None

        self.configure(bg=self._OWN_BG)
        # Load last N turns from persistent history into session memory
        self._restore_session_memory()

        self._load_kirito_image()
        self._build_ui()
        self._post_greeting()

    def _restore_session_memory(self, max_turns: int = 20):
        """Feed recent chat history into the session so Kirito remembers past talks."""
        if not self.history_log:
            return
        # Take last max_turns*2 entries (each turn = USER + KIRITO)
        recent = self.history_log[-(max_turns * 2):]
        for entry in recent:
            role = "user" if entry.get("role") == "USER" else "assistant"
            self.session.add(role, entry.get("text", ""))

    # ------------------------------------------------------------------
    # Image loading
    # ------------------------------------------------------------------

    def _load_kirito_image(self):
        """Load the embedded Kirito avatar image from base64."""
        try:
            from PIL import Image, ImageTk
            import base64, io
            img_data = base64.b64decode(KIRITO_IMAGE_B64)
            img = Image.open(io.BytesIO(img_data))
            img.thumbnail((200, 320), Image.LANCZOS)
            self.kirito_image = ImageTk.PhotoImage(img)
            return
        except ImportError:
            pass
        self.kirito_image = None

    # ------------------------------------------------------------------
    # UI Build
    # ------------------------------------------------------------------

    def _build_ui(self):
        # ── Header bar ──────────────────────────────────────────────
        header = tk.Frame(self, bg=KIRITO_HEADER_BG, height=52)
        header.pack(fill=tk.X, side=tk.TOP)
        header.pack_propagate(False)

        tk.Label(header, text="⚔  Kirito  ⚔",
                 bg=KIRITO_HEADER_BG, fg=KIRITO_TITLE_CLR,
                 font=("Segoe UI", 15, "bold")).pack(side=tk.LEFT, padx=18, pady=10)

        self.mood_btn = tk.Button(
            header, text=f"  {self.current_mood} —  ",
            bg=KIRITO_NEUTRAL_BTN, fg="#ffffff",
            font=("Segoe UI", 10), relief=tk.FLAT,
            bd=0, padx=8, pady=4,
            cursor="hand2",
            command=self._change_mood
        )
        self.mood_btn.pack(side=tk.RIGHT, padx=14, pady=10)

        # ── Main content area ────────────────────────────────────────
        content = tk.Frame(self, bg=KIRITO_BG_DARK)
        content.pack(fill=tk.BOTH, expand=True)

        # Left: chat + input
        left_frame = tk.Frame(content, bg=KIRITO_BG_DARK)
        left_frame.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        # Chat canvas with scrollbar
        chat_outer = tk.Frame(left_frame, bg=KIRITO_BG_PANEL)
        chat_outer.pack(fill=tk.BOTH, expand=True)

        self.chat_canvas = tk.Canvas(chat_outer, bg=KIRITO_BG_PANEL,
                                     highlightthickness=0, bd=0)
        self.chat_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        scrollbar = tk.Scrollbar(chat_outer, orient=tk.VERTICAL,
                                  command=self.chat_canvas.yview)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        self.chat_canvas.configure(yscrollcommand=scrollbar.set)
        self.chat_canvas.bind("<Configure>",
                               lambda e: self.chat_canvas.configure(
                                   scrollregion=self.chat_canvas.bbox("all")))

        self.messages_frame = tk.Frame(self.chat_canvas, bg=KIRITO_BG_PANEL)
        self.chat_canvas_window = self.chat_canvas.create_window(
            (0, 0), window=self.messages_frame, anchor="nw")
        self.chat_canvas.bind("<Configure>", self._on_canvas_resize)

        # Mouse wheel scrolling
        self.chat_canvas.bind_all("<MouseWheel>",
                                   lambda e: self.chat_canvas.yview_scroll(
                                       -1 * (e.delta // 120), "units")
                                   if self.chat_canvas.winfo_exists() else None)

        # ── Input row ───────────────────────────────────────────────
        input_frame = tk.Frame(left_frame, bg=KIRITO_HEADER_BG, height=60)
        input_frame.pack(fill=tk.X, side=tk.BOTTOM)
        input_frame.pack_propagate(False)

        self.input_var = tk.StringVar()
        self.input_box = tk.Entry(
            input_frame, textvariable=self.input_var,
            bg=KIRITO_INPUT_BG, fg="#ffffff", insertbackground="#ffffff",
            relief=tk.FLAT, font=("Segoe UI", 11),
            bd=0
        )
        self.input_box.pack(side=tk.LEFT, fill=tk.BOTH, expand=True,
                            padx=(10, 6), pady=12)
        self.input_box.bind("<Return>", lambda e: self._send())

        def _make_btn(parent, text, cmd, icon=""):
            b = tk.Button(parent, text=f"{icon} {text}" if icon else text,
                          bg=KIRITO_BUTTON_SEND, fg="#ffffff",
                          font=("Segoe UI", 10, "bold"),
                          relief=tk.FLAT, bd=0,
                          padx=10, pady=6,
                          cursor="hand2",
                          activebackground="#4f6ee0",
                          activeforeground="#ffffff",
                          command=cmd)
            b.pack(side=tk.LEFT, padx=3, pady=10)
            return b

        _make_btn(input_frame, "Send",  self._send)
        _make_btn(input_frame, "⚙",    self._open_settings)
        _make_btn(input_frame, "Lore",  self._show_lore,  "📖")
        _make_btn(input_frame, "Hist",  self._show_history, "📋")
        _make_btn(input_frame, "Clear", self._clear_chat,  "🗑")

        # ── Status bar ──────────────────────────────────────────────
        self.status_var = tk.StringVar(value="Kirito is here. Say something.")
        status_bar = tk.Label(self, textvariable=self.status_var,
                              bg=KIRITO_HEADER_BG, fg=KIRITO_STATUS_CLR,
                              font=("Segoe UI", 9), anchor="w")
        status_bar.pack(fill=tk.X, side=tk.BOTTOM)

        # ── Right sidebar ────────────────────────────────────────────
        sidebar = tk.Frame(content, bg=KIRITO_SIDEBAR_BG, width=220)
        sidebar.pack(side=tk.RIGHT, fill=tk.Y)
        sidebar.pack_propagate(False)

        self._build_sidebar(sidebar)

    def _build_sidebar(self, sidebar: tk.Frame):
        # Avatar image area
        avatar_frame = tk.Frame(sidebar, bg=KIRITO_SIDEBAR_BG)
        avatar_frame.pack(fill=tk.X, padx=6, pady=(8, 2))

        if self.kirito_image:
            img_label = tk.Label(avatar_frame, image=self.kirito_image,
                                  bg=KIRITO_SIDEBAR_BG, relief=tk.FLAT)
            img_label.pack()
        else:
            # Placeholder blue box with text
            placeholder = tk.Canvas(avatar_frame, width=200, height=220,
                                     bg="#0f1a2b", highlightthickness=1,
                                     highlightbackground="#5b21b6")
            placeholder.pack()
            placeholder.create_text(100, 110, text="⚔ Kirito ⚔",
                                     fill="#7dd3fc", font=("Segoe UI", 16, "bold"))

        self.avatar_status = tk.Label(
            sidebar, text="— watching quietly —",
            bg=KIRITO_SIDEBAR_BG, fg=KIRITO_MOOD_CLR,
            font=("Segoe UI", 9)
        )
        self.avatar_status.pack(pady=(2, 6))

        # Mentor Stats box
        stats_frame = tk.LabelFrame(
            sidebar, text=" Mentor Stats ",
            bg=KIRITO_SIDEBAR_BG, fg=BOND_LABEL,
            font=("Segoe UI", 9, "bold"),
            relief=tk.SOLID, bd=1,
            labelanchor="nw"
        )
        stats_frame.pack(fill=tk.X, padx=6, pady=4)

        # Discipline bar
        tk.Label(stats_frame, text="Discipline", bg=KIRITO_SIDEBAR_BG,
                 fg="#ffffff", font=("Segoe UI", 9)).grid(
            row=0, column=0, padx=6, pady=4, sticky="w")
        disc_canvas = tk.Canvas(stats_frame, bg=BOND_BAR_BG,
                                  height=14, width=110, highlightthickness=0)
        disc_canvas.grid(row=0, column=1, padx=6, pady=4)
        self.disc_bar_canvas = disc_canvas
        self.disc_bar = disc_canvas.create_rectangle(
            0, 0, int(110 * self.bond.discipline / 100), 14,
            fill=BOND_BAR_FG, outline=""
        )

        # Focus bar
        tk.Label(stats_frame, text="Focus", bg=KIRITO_SIDEBAR_BG,
                 fg="#ffffff", font=("Segoe UI", 9)).grid(
            row=1, column=0, padx=6, pady=4, sticky="w")
        focus_canvas = tk.Canvas(stats_frame, bg=BOND_BAR_BG,
                                height=14, width=110, highlightthickness=0)
        focus_canvas.grid(row=1, column=1, padx=6, pady=4)
        self.focus_bar_canvas = focus_canvas
        self.focus_bar = focus_canvas.create_rectangle(
            0, 0, int(110 * self.bond.focus / 100), 14,
            fill=BOND_BAR_FG, outline=""
        )

        # Sessions counter
        tk.Label(stats_frame, text="Sessions", bg=KIRITO_SIDEBAR_BG,
                 fg="#ffffff", font=("Segoe UI", 9)).grid(
            row=2, column=0, padx=6, pady=4, sticky="w")
        self.sessions_label = tk.Label(stats_frame, text=str(self.bond.sessions),
                                        bg=KIRITO_SIDEBAR_BG, fg=BOND_VALUE,
                                        font=("Segoe UI", 9, "bold"))
        self.sessions_label.grid(row=2, column=1, padx=6, pady=4, sticky="w")

        # Stage label
        tk.Label(stats_frame, text="Stage", bg=KIRITO_SIDEBAR_BG,
                 fg="#ffffff", font=("Segoe UI", 9)).grid(
            row=3, column=0, padx=6, pady=4, sticky="w")
        self.stage_label = tk.Label(stats_frame, text=self.bond.stage,
                                     bg=KIRITO_SIDEBAR_BG, fg=BOND_VALUE,
                                     font=("Segoe UI", 9, "bold"))
        self.stage_label.grid(row=3, column=1, padx=6, pady=4, sticky="w")

    def _on_canvas_resize(self, event):
        self.chat_canvas.itemconfig(self.chat_canvas_window, width=event.width)
        self.chat_canvas.configure(scrollregion=self.chat_canvas.bbox("all"))

    # ------------------------------------------------------------------
    # Message bubbles
    # ------------------------------------------------------------------

    def _add_bubble(self, role: str, text: str, timestamp: str = ""):
        """Add a chat bubble. role = 'user' | 'kirito'"""
        if not timestamp:
            timestamp = datetime.now().strftime("%H:%M")

        outer = tk.Frame(self.messages_frame, bg=KIRITO_BG_PANEL)
        outer.pack(fill=tk.X, padx=10, pady=4)

        if role == "kirito":
            # Left-aligned bubble with styled imagery + dialogue split
            bubble_frame = tk.Frame(outer, bg=KIRITO_BG_PANEL)
            bubble_frame.pack(anchor="w", fill=tk.X)

            name_lbl = tk.Label(bubble_frame, text="KIRITO",
                                 bg=KIRITO_BG_PANEL, fg=KIRITO_NAME_CLR,
                                 font=("Segoe UI", 8, "bold"))
            name_lbl.pack(anchor="w", padx=2)

            bubble = tk.Frame(bubble_frame, bg=KIRITO_BUBBLE,
                               padx=12, pady=8)
            bubble.pack(anchor="w", fill=tk.X)

            # Parse imagery (*...*) and dialogue lines
            imagery_line, dialogue_line = _split_kirito_response(text)

            if imagery_line:
                img_lbl = tk.Label(
                    bubble, text=f"*{imagery_line}*",
                    bg=KIRITO_BUBBLE, fg="#c4b5fd",
                    font=("Segoe UI", 10, "italic"),
                    wraplength=480, justify=tk.LEFT, anchor="w"
                )
                img_lbl.pack(anchor="w", pady=(0, 4))

            # If parser found dialogue use it; if only imagery exists show
            # it as dialogue too; last resort show raw text
            display_text = dialogue_line or (text if not imagery_line else "")
            msg_label = tk.Label(
                bubble, text=display_text,
                bg=KIRITO_BUBBLE, fg="#ffffff",
                font=("Segoe UI", 11),
                wraplength=480, justify=tk.LEFT, anchor="w"
            )
            msg_label.pack(anchor="w")

            ts_lbl = tk.Label(bubble, text=timestamp,
                               bg=KIRITO_BUBBLE, fg=TIMESTAMP_CLR,
                               font=("Segoe UI", 8))
            ts_lbl.pack(anchor="e")

        else:
            # Right-aligned bubble
            bubble_frame = tk.Frame(outer, bg=KIRITO_BG_PANEL)
            bubble_frame.pack(anchor="e")

            name_lbl = tk.Label(bubble_frame, text="USER",
                                 bg=KIRITO_BG_PANEL, fg=USER_NAME_CLR,
                                 font=("Segoe UI", 8, "bold"))
            name_lbl.pack(anchor="e", padx=2)

            bubble = tk.Frame(bubble_frame, bg=KIRITO_USER_BUBBLE,
                               padx=12, pady=8)
            bubble.pack(anchor="e")

            msg_label = tk.Label(
                bubble, text=text,
                bg=KIRITO_USER_BUBBLE, fg="#ffffff",
                font=("Segoe UI", 11),
                wraplength=380, justify=tk.LEFT, anchor="w"
            )
            msg_label.pack(anchor="w")

            ts_lbl = tk.Label(bubble, text=timestamp,
                               bg=KIRITO_USER_BUBBLE, fg=TIMESTAMP_CLR,
                               font=("Segoe UI", 8))
            ts_lbl.pack(anchor="e")

        self._scroll_bottom()
        return msg_label  # return label so streaming can update it

    def _scroll_bottom(self):
        self.messages_frame.update_idletasks()
        self.chat_canvas.configure(
            scrollregion=self.chat_canvas.bbox("all"))
        self.chat_canvas.yview_moveto(1.0)

    # ------------------------------------------------------------------
    # Streaming bubble
    # ------------------------------------------------------------------

    def _add_streaming_bubble(self):
        """Add a bubble that will be updated token-by-token."""
        timestamp = datetime.now().strftime("%H:%M")
        outer = tk.Frame(self.messages_frame, bg=KIRITO_BG_PANEL)
        outer.pack(fill=tk.X, padx=10, pady=4)

        name_lbl = tk.Label(outer, text="KIRITO", bg=KIRITO_BG_PANEL,
                             fg=KIRITO_NAME_CLR, font=("Segoe UI", 8, "bold"))
        name_lbl.pack(anchor="w", padx=2)

        bubble = tk.Frame(outer, bg=KIRITO_BUBBLE, padx=12, pady=8)
        bubble.pack(anchor="w", fill=tk.X)

        # Imagery placeholder (italic, lavender)
        self._stream_img_label = tk.Label(
            bubble, text="",
            bg=KIRITO_BUBBLE, fg="#c4b5fd",
            font=("Segoe UI", 10, "italic"),
            wraplength=480, justify=tk.LEFT, anchor="w"
        )
        self._stream_img_label.pack(anchor="w")

        # Dialogue placeholder
        self._stream_label = tk.Label(
            bubble, text="▌",
            bg=KIRITO_BUBBLE, fg="#ffffff",
            font=("Segoe UI", 11),
            wraplength=480, justify=tk.LEFT, anchor="w"
        )
        self._stream_label.pack(anchor="w")

        self._stream_ts = tk.Label(bubble, text=timestamp,
                                    bg=KIRITO_BUBBLE, fg=TIMESTAMP_CLR,
                                    font=("Segoe UI", 8))
        self._stream_ts.pack(anchor="e")

        self._stream_text = ""
        self._scroll_bottom()

    def _append_stream_token(self, token: str):
        """Called from background thread — schedules UI update."""
        self._stream_text += token
        self.after(0, self._update_stream_label)

    def _update_stream_label(self):
        if hasattr(self, "_stream_label"):
            imagery_line, dialogue_line = _split_kirito_response(self._stream_text)
            if imagery_line and hasattr(self, "_stream_img_label"):
                self._stream_img_label.config(text=f"*{imagery_line}*")
                self._stream_label.config(
                    text=(dialogue_line + "▌") if dialogue_line else "▌")
            else:
                self._stream_label.config(text=self._stream_text + "▌")
        self._scroll_bottom()

    def _finalize_stream(self):
        if hasattr(self, "_stream_label") and hasattr(self, "_stream_img_label"):
            final = _normalize_reply(self._stream_text)
            imagery_line, dialogue_line = _split_kirito_response(final)
            if imagery_line:
                self._stream_img_label.config(text=f"*{imagery_line}*")
            self._stream_label.config(
                text=dialogue_line if dialogue_line else self._stream_text)
        elif hasattr(self, "_stream_label"):
            self._stream_label.config(text=self._stream_text)

    # ------------------------------------------------------------------
    # Send / Chat
    # ------------------------------------------------------------------

    def _send(self):
        if self.is_typing:
            return
        text = self.input_var.get().strip()
        if not text:
            return

        self.input_var.set("")
        ts = datetime.now().strftime("%H:%M")

        # Append to persistent log
        self.history_log.append({"time": ts, "role": "USER", "text": text})
        save_kirito_history(self.history_log)

        self._add_bubble("user", text, ts)

        self.is_typing = True
        self.status_var.set("Kirito is thinking...")
        self.avatar_status.config(text="... processing")

        def run():
            try:
                if self.session.stream:
                    self.after(0, self._add_streaming_bubble)
                    time.sleep(0.05)  # let UI render
                    reply = kirito_chat(self.session, text,
                                 stream_callback=self._append_stream_token)
                    self.after(0, self._finalize_stream)
                else:
                    reply = kirito_chat(self.session, text)
                    self.after(0, lambda: self._add_bubble("kirito", reply))
            except Exception as e:
                reply = f"[Error: {e}]"
                self.after(0, lambda: self._add_bubble("kirito", reply))

            ts2 = datetime.now().strftime("%H:%M")
            self.history_log.append({"time": ts2, "role": "KIRITO", "text": reply})
            save_kirito_history(self.history_log)

            self.bond.update(text, reply)
            self.after(0, self._update_bond_bars)
            self.after(0, lambda: self.status_var.set(
                "Kirito is here. Say something."))
            self.after(0, lambda: self.avatar_status.config(
                text=f"— {self.current_mood.lower()} —"))
            self.after(0, lambda: setattr(self, "is_typing", False))

            # Kirito farewell — show a goodbye bubble then close
            if re.match(r"^(bye+|goodbye|see you|cya|good night|goodnight)\W*$",
                        text.strip(), re.IGNORECASE):
                farewell = (
                    "*He gives a small nod, expression steady.*\n"
                    "All right, Adi. Get some rest. Come back when you are ready to move forward."
                )
                self.after(1200, lambda: self._add_bubble(
                    "kirito", farewell, datetime.now().strftime("%H:%M")))
                self.after(30000, self.destroy)

        threading.Thread(target=run, daemon=True).start()

    # ------------------------------------------------------------------
    # Bond bars
    # ------------------------------------------------------------------

    def _update_bond_bars(self):
        dw = int(110 * self.bond.discipline / 100)
        fw = int(110 * self.bond.focus / 100)
        self.disc_bar_canvas.coords(self.disc_bar, 0, 0, dw, 14)
        self.focus_bar_canvas.coords(self.focus_bar, 0, 0, fw, 14)
        self.sessions_label.config(text=str(self.bond.sessions))
        self.stage_label.config(text=self.bond.stage)

    # ------------------------------------------------------------------
    # Greeting
    # ------------------------------------------------------------------

    def _post_greeting(self):
        # Check if returning user
        if self.history_log:
            last_user = next((e["text"] for e in reversed(self.history_log)
                              if e.get("role") == "USER"), None)
            if last_user:
                greeting = (
                    "*He looks at you with a steady, measured gaze.*\n"
                    "You are back, Adi. Good. What are we working on today."
                )
            else:
                greeting = (
                    "*He stands with his arms crossed, expression focused.*\n"
                    "You came back. That already says something. Let us not waste it."
                )
        else:
            greeting = (
                "*He glances over, calm and unhurried, then looks forward again.*\n"
                "Adi. You showed up. That is the first step — most people do not even get that far."
            )
        self.after(300, lambda: self._add_bubble(
            "kirito", greeting, datetime.now().strftime("%H:%M")
        ))

    # ------------------------------------------------------------------
    # Dialogs
    # ------------------------------------------------------------------

    def _change_mood(self):
        mood = simpledialog.askstring(
            "Set Mood",
            "Enter focus mode for Kirito (e.g. 'training', 'intense', 'focused'):",
            parent=self
        )
        if mood:
            self.current_mood = mood.strip().capitalize()
            self.session.mood_hint = mood.strip()
            self.mood_btn.config(text=f"  {self.current_mood} —  ")
            self.avatar_status.config(
                text=f"— {self.current_mood.lower()} —")

    def _open_settings(self):
        win = tk.Toplevel(self)
