class Trio_TrioApp(tk.Frame):
    def __init__(self, parent, miku, yuhee, max_history):
        super().__init__(parent, bg=Trio_BG_DARK)
        self.pack(fill="both", expand=True)
        self.miku        = miku
        self.yuhee       = yuhee
        self.max_history = max_history
        self.is_typing   = False
        self.history_log = Trio_load_history()

        # ONE shared log — both bots read from this. No separate deques.
        self.shared_log: List[dict] = []

        # Alternating first-speaker: True = Yuhee first, False = Miku first
        self._yuhee_first = True
        

        self._build_ui()
        self._post_greeting()

    # ------------------------------------------------------------------
    # UI
    # ------------------------------------------------------------------

    def _build_ui(self):
        # Header
        header = tk.Frame(self, bg=Trio_HEADER_BG, height=54)
        header.pack(fill=tk.X, side=tk.TOP)
        header.pack_propagate(False)

        tk.Label(header,
                 text="🎧  Miku  ×  Yuhee  ×  Adi-kun  🌸",
                 bg=Trio_HEADER_BG, fg=Trio_TITLE_CLR,
                 font=("Segoe UI", 14, "bold")).pack(side=tk.LEFT, padx=18, pady=12)

        tk.Label(header,
                 text="Group Chat",
                 bg=Trio_HEADER_BG, fg=Trio_STATUS_CLR,
                 font=("Segoe UI", 9)).pack(side=tk.RIGHT, padx=18)

        # Main content
        content = tk.Frame(self, bg=Trio_BG_DARK)
        content.pack(fill=tk.BOTH, expand=True)

        # Left: chat
        left = tk.Frame(content, bg=Trio_BG_DARK)
        left.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        chat_outer = tk.Frame(left, bg=Trio_BG_PANEL)
        chat_outer.pack(fill=tk.BOTH, expand=True)

        self.chat_canvas = tk.Canvas(chat_outer, bg=Trio_BG_PANEL,
                                     highlightthickness=0, bd=0)
        self.chat_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        scrollbar = tk.Scrollbar(chat_outer, orient=tk.VERTICAL,
                                 command=self.chat_canvas.yview)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        self.chat_canvas.configure(yscrollcommand=scrollbar.set)

        self.messages_frame = tk.Frame(self.chat_canvas, bg=Trio_BG_PANEL)
        self.canvas_window = self.chat_canvas.create_window(
            (0, 0), window=self.messages_frame, anchor="nw")
        self.chat_canvas.bind("<Configure>", self._on_canvas_resize)
        self.chat_canvas.bind_all("<MouseWheel>",
            lambda e: self.chat_canvas.yview_scroll(-1 * (e.delta // 120), "units")
            if self.chat_canvas.winfo_exists() else None)

        # Input row
        input_frame = tk.Frame(left, bg=Trio_HEADER_BG, height=62)
        input_frame.pack(fill=tk.X, side=tk.BOTTOM)
        input_frame.pack_propagate(False)

        self.input_var = tk.StringVar()
        self.input_box = tk.Entry(
            input_frame, textvariable=self.input_var,
            bg=Trio_INPUT_BG, fg="#ffffff", insertbackground="#ffffff",
            relief=tk.FLAT, font=("Segoe UI", 11), bd=0
        )
        self.input_box.pack(side=tk.LEFT, fill=tk.BOTH, expand=True,
                            padx=(12, 6), pady=14)
        self.input_box.bind("<Return>", lambda e: self._send())

        def _btn(text, cmd, color=Trio_BUTTON_SEND):
            b = tk.Button(input_frame, text=text,
                          bg=color, fg="#ffffff",
                          font=("Segoe UI", 10, "bold"),
                          relief=tk.FLAT, bd=0, padx=10, pady=6,
                          cursor="hand2",
                          activebackground=Trio_BUTTON_HOV,
                          activeforeground="#ffffff",
                          command=cmd)
            b.pack(side=tk.LEFT, padx=3, pady=12)
            return b

        _btn("Send", self._send)
        _btn("📖 Hist", self._open_history, Trio_NEUTRAL_BTN)
        _btn("🗑 Clear", self._clear_chat, Trio_NEUTRAL_BTN)

        # Status bar
        self.status_var = tk.StringVar(value="Everyone is here. Say something!")
        tk.Label(self, textvariable=self.status_var,
                 bg=Trio_HEADER_BG, fg=Trio_STATUS_CLR,
                 font=("Segoe UI", 9), anchor="w").pack(fill=tk.X, side=tk.BOTTOM)

        # Right sidebar
