#  IMAGE UTILITIES
# ════════════════════════════════════════════════════════════════════


def _make_circle_image(b64_str: str, size: int = 110) -> ImageTk.PhotoImage | None:
    """Decode base64, fit image within square (no crop/stretch), return PhotoImage. Returns None on failure."""
    if not b64_str.strip():
        return None
    try:
        data = base64.b64decode(b64_str)
        img = Image.open(io.BytesIO(data)).convert("RGBA")
        # Fit within size×size without cropping or distorting
        img.thumbnail((size, size), Image.LANCZOS)
        # Paste onto a transparent canvas so the button background shows through
        canvas = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        offset = ((size - img.width) // 2, (size - img.height) // 2)
        canvas.paste(img, offset, img)
        return ImageTk.PhotoImage(canvas)
    except Exception:
        return None


def _make_placeholder_avatar(label: str, size: int, bg_color: str, fg_color: str) -> ImageTk.PhotoImage:
    """Generate a circular avatar with initials when no image is provided."""
    img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    draw = ImageDraw.Draw(img)
    # Parse hex color
    def hex_to_rgb(h):
        h = h.lstrip("#")
        return tuple(int(h[i:i+2], 16) for i in (0, 2, 4))
    r, g, b = hex_to_rgb(bg_color)
    draw.rectangle((0, 0, size, size), fill=(r, g, b, 220))
    draw.rectangle((3, 3, size-3, size-3), outline=hex_to_rgb(fg_color) + (180,), width=2)
    # Draw initials
    fr, fg2, fb = hex_to_rgb(fg_color)
    text = label[:2].upper()
    draw.text((size//2, size//2), text, fill=(fr, fg2, fb, 255), anchor="mm")
    return ImageTk.PhotoImage(img)


