#  MAIN APPLICATION CLASS
# ════════════════════════════════════════════════════════════════════

class AnimeLauncher:
    def __init__(self):
        self.root = tk.Tk()
        self.root.title("✦ Anime Personality AI Chatbox ✦")
        self.root.geometry("900x600")
        self.root.minsize(900, 600)
        self.root.configure(bg=THEME["bg"])
        self.root.resizable(True, True)
        self.root.protocol("WM_DELETE_WINDOW", self._on_close)   # ← hook added here

        # Cache for PhotoImages (must keep references or GC destroys them)
        self._img_cache: dict[str, ImageTk.PhotoImage] = {}

        # The single content area that swaps between home & apps
        self._current_frame: tk.Frame | None = None

        self._build_header()
        self._content_area = tk.Frame(self.root, bg=THEME["bg"])
        self._content_area.pack(fill="both", expand=True, padx=0, pady=0)
        self.show_home()

        # Ollama/model readiness is checked silently in the background —
        # the window is already up and usable while this runs.
        threading.Thread(target=self._startup_check, daemon=True).start()

        self.root.mainloop()

    def _startup_check(self):
        try:
            ensure_ollama_running()
        except Exception:
            pass

    def _on_close(self):          # ← ADD THIS METHOD HERE, right after __init__
        # Silent, immediate shutdown — no dialogs, no output.
        self.root.protocol("WM_DELETE_WINDOW", lambda: None)  # ignore repeat clicks
        try:
            stop_ollama()   # no-op (returns instantly) unless this app started Ollama
        except Exception:
            pass
        self.root.destroy()

    # ── Header ────────────────────────────────────────────────────

    def _build_header(self):
        hdr = tk.Frame(self.root, bg="#0d0d22", height=54)
        hdr.pack(fill="x", side="top")
        hdr.pack_propagate(False)

        # Back button — hidden initially
        self._back_btn = tk.Button(
            hdr,
            text="↩  Back",
            font=THEME["back_font"],
            fg=THEME["subtext"],
            bg="#0d0d22",
            activebackground="#1a1a3a",
            activeforeground=THEME["text"],
            bd=0, padx=12, pady=6,
            cursor="hand2",
            command=self.show_home,
        )
        self._back_btn.place(x=10, rely=0.5, anchor="w")
        self._back_btn.place_forget()  # hide on launch

        # Title
        tk.Label(
            hdr,
            text="✦  ANIME PERSONALITY AI CHATBOX  ✦",
            font=("Yu Gothic UI", 15, "bold"),
            fg=THEME["text"],
            bg="#0d0d22",
        ).place(relx=0.5, rely=0.5, anchor="center")

        # Separator line
        sep = tk.Frame(self.root, bg=THEME["border"], height=1)
        sep.pack(fill="x")

    # ── Navigation ────────────────────────────────────────────────

    def show_home(self):
        self._swap_frame(self._build_home_frame)
        self._back_btn.place_forget()

    def open_app(self, char: dict):
        def builder(parent):
            return self._build_app_frame(parent, char)
        self._swap_frame(builder)
        # Show back button
        self._back_btn.configure(
            text=f"↩  {char['name']}",
            fg=char["accent"],
        )
        self._back_btn.place(x=10, rely=0.5, anchor="w")

    def _swap_frame(self, builder_fn):
        if self._current_frame:
            self._current_frame.destroy()
        frame = tk.Frame(self._content_area, bg=THEME["bg"])
        frame.pack(fill="both", expand=True)
        self._current_frame = frame
        builder_fn(frame)

    # ── Home Screen ───────────────────────────────────────────────

    def _build_home_frame(self, parent: tk.Frame):
        # Subtitle
        tk.Label(
            parent,
            text="Choose your companion",
            font=("Yu Gothic UI", 11),
            fg=THEME["subtext"],
            bg=THEME["bg"],
        ).pack(pady=(18, 4))

        # Decorative divider
        div = tk.Frame(parent, bg=THEME["border"], height=1)
        div.pack(fill="x", padx=80, pady=(0, 20))

        # ── Row 1: 3 cards (Miku, Rem, Yuhee) ────────────────
        row1 = tk.Frame(parent, bg=THEME["bg"])
        row1.pack(anchor="center")
        for char in CHARACTERS[:3]:
            self._character_card(row1, char).pack(side="left", padx=18, pady=6)

        # ── Row 2: 2 cards centred (Kirito, Lelouch) ─────────
        row2 = tk.Frame(parent, bg=THEME["bg"])
        row2.pack(anchor="center", pady=(10, 0))
        for char in CHARACTERS[3:5]:
            self._character_card(row2, char).pack(side="left", padx=18, pady=6)

        # ── Row 3: 1 card centred (Trio_chat_Yuhee_and_Miku) ──
        row3 = tk.Frame(parent, bg=THEME["bg"])
        row3.pack(anchor="center", pady=(10, 0))
        self._character_card(row3, CHARACTERS[5]).pack(side="left", padx=18, pady=6)

        # Footer
        tk.Label(
            parent,
            text="Click a card to open the app",
            font=("Yu Gothic UI", 9),
            fg="#44446a",
            bg=THEME["bg"],
        ).pack(pady=(24, 0))

    def _character_card(self, parent: tk.Frame, char: dict) -> tk.Frame:
        accent = char["accent"]

        # Outer card
        card = tk.Frame(
            parent,
            bg=THEME["surface"],
            bd=1,
            relief="flat",
            cursor="hand2",
            width=190, height=210,
        )
        card.pack_propagate(False)

        # Accent top bar
        tk.Frame(card, bg=accent, height=3).pack(fill="x")

        # Avatar
        img = self._get_avatar(char, size=120)
        av_label = tk.Label(card, image=img, bg=THEME["surface"], cursor="hand2")
        av_label.image = img  # keep ref
        av_label.pack(pady=(10, 4))

        # Name
        name_lbl = tk.Label(
            card,
            text=char["name"],
            font=("Yu Gothic UI", 12, "bold"),
            fg=accent, bg=THEME["surface"],
            cursor="hand2",
            wraplength=180,
            justify="center",
        )
        name_lbl.pack(pady=(0, 10))

        # Hover effects
        def on_enter(_):
            card.config(bg="#1c1c3e")
            for w in card.winfo_children():
                try:
                    w.config(bg="#1c1c3e")
                except Exception:
                    pass
            av_label.config(bg="#1c1c3e")
            name_lbl.config(bg="#1c1c3e")

        def on_leave(_):
            card.config(bg=THEME["surface"])
            for w in card.winfo_children():
                try:
                    if not isinstance(w, tk.Frame):
                        w.config(bg=THEME["surface"])
                except Exception:
                    pass

        def on_click(_):
            self.open_app(char)

        for widget in [card, av_label, name_lbl]:
            widget.bind("<Enter>", on_enter)
            widget.bind("<Leave>", on_leave)
            widget.bind("<Button-1>", on_click)

        return card

    def _get_avatar(self, char: dict, size: int = 90) -> ImageTk.PhotoImage:
        key = f"{char['key']}_{size}"
        if key in self._img_cache:
            return self._img_cache[key]
        b64 = char["b64"]()
        img = _make_circle_image(b64, size)
        if img is None:
            img = _make_placeholder_avatar(char["name"], size, char["accent"], "#ffffff")
        self._img_cache[key] = img
        return img

    # ── App Frame ─────────────────────────────────────────────────

    def _build_app_frame(self, parent: tk.Frame, char: dict):
        accent = char["accent"]

        # Thin accent bar at top of content
        tk.Frame(parent, bg=accent, height=2).pack(fill="x")

        # App title strip
        strip = tk.Frame(parent, bg=THEME["surface"], height=38)
        strip.pack(fill="x")
        strip.pack_propagate(False)
        tk.Label(
            strip,
            text=f"✦  {char['name'].upper()}",
            font=("Yu Gothic UI", 10, "bold"),
            fg=accent, bg=THEME["surface"],
        ).pack(side="left", padx=16, pady=8)

        # Container for the actual app UI — no bg forced, let each app set its own
        app_container = tk.Frame(parent)
        app_container.pack(fill="both", expand=True)

        # Call the registered launch function
        launcher_fn = APP_REGISTRY.get(char["key"])
        if launcher_fn:
            try:
                launcher_fn(app_container)
            except Exception as e:
                tk.Label(
                    app_container,
                    text=f"Error launching {char['name']}:\n{e}",
                    font=("Consolas", 11),
                    fg="#ff4444",
                ).pack(pady=60)
        else:
            tk.Label(
                app_container,
                text="No launcher registered.",
                fg=THEME["subtext"], bg=THEME["bg"],
            ).pack(pady=60)


